      const dby = dFy;

      const Fxy2 = bx * bx + by * by;
      const Fxy = Math.sqrt(Fxy2);
      const F2 = Fxy2 + bz * bz;

      const pitchDes = clamp(Math.atan2(bx, by), -0.58, 0.58);
      const rollDes = clamp(Math.atan2(-bz, Fxy), -0.58, 0.58);

      const pitchRateDes = clamp((by * dbx - bx * dby) / Math.max(1e-4, Fxy2), -6, 6);
      const dFxy = (bx * dbx + by * dby) / Math.max(1e-4, Fxy);
      const rollRateDes = clamp((-Fxy * dbz + bz * dFxy) / Math.max(1e-4, F2), -6, 6);

      const cosTilt = Math.max(0.5, Math.cos(att.roll) * Math.cos(att.pitch));
      const Fdes = Fy / cosTilt;
      const dFdes = dFy / cosTilt + Fdes * (Math.tan(att.pitch) * rates.pitch + Math.tan(att.roll) * rates.roll);
      const Ftarget = clamp(Fdes + 0.75 * params.lag * dFdes, 0.5, 15.5);

      const inertia = TASK.inertia * params.mass / TASK.baseMass;
      const tauRollDes = inertia * (75 * (rollDes - att.roll) + 15 * (rollRateDes - rates.roll) + 0.4 * rates.roll);
      const tauPitchDes = inertia * (75 * (pitchDes - att.pitch) + 15 * (pitchRateDes - rates.pitch) + 0.4 * rates.pitch);
