      const weakness = params.weakness;
      const targetW = Ftarget / 4 +
        tauRollDes * MOTOR_Z[w] / (4 * TASK.arm) -
        tauPitchDes * MOTOR_X[w] / (4 * TASK.arm) +
        tauYawDes * SPIN[w] / (4 * TASK.yawCoefficient);

