      const dbz = sy * dFx + cy * dFz + rates.yaw * bx;
      const dby = dFy;

      const Fxy2 = bx * bx + by * by;
      const Fxy = Math.sqrt(Fxy2);
      const F2 = Fxy2 + bz * bz;

